import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/foundation.dart';

/// Build-time configuration passed with `--dart-define-from-file`.
///
/// Architecture decision: instead of committing a `firebase_options.dart`
/// generated by `flutterfire configure`, the Firebase options are injected per
/// flavor (`env/dev.json`, `env/prod.json`, both git-ignored). This keeps dev
/// and prod projects separate and nothing project-specific in source control.
/// The values themselves come from the Firebase console or from running
/// `flutterfire configure` once and copying them over (see README).
abstract final class Env {
  static const String flavor = String.fromEnvironment(
    'APP_FLAVOR',
    defaultValue: 'dev',
  );

  static const String _apiKey = String.fromEnvironment('FIREBASE_API_KEY');
  static const String _appId = String.fromEnvironment('FIREBASE_APP_ID');
  static const String _senderId = String.fromEnvironment(
    'FIREBASE_MESSAGING_SENDER_ID',
  );
  static const String _projectId = String.fromEnvironment(
    'FIREBASE_PROJECT_ID',
  );
  static const String _storageBucket = String.fromEnvironment(
    'FIREBASE_STORAGE_BUCKET',
  );
  static const String _iosBundleId = String.fromEnvironment(
    'FIREBASE_IOS_BUNDLE_ID',
  );
  static const String _webAuthDomain = String.fromEnvironment(
    'FIREBASE_AUTH_DOMAIN',
  );

  /// reCAPTCHA v3 site key for App Check on web (optional).
  static const String recaptchaSiteKey = String.fromEnvironment(
    'RECAPTCHA_SITE_KEY',
  );

  /// When true, Auth and Firestore talk to the local Emulator Suite.
  static const bool useEmulator = bool.fromEnvironment('USE_FIREBASE_EMULATOR');

  /// Host of the emulator. `10.0.2.2` reaches the host machine from the
  /// Android emulator; use your PC's LAN IP for a physical device.
  static const String emulatorHost = String.fromEnvironment(
    'FIREBASE_EMULATOR_HOST',
    defaultValue: '10.0.2.2',
  );
  static const int authEmulatorPort = 9099;
  static const int firestoreEmulatorPort = 8080;

  static bool get isProd => flavor == 'prod';

  /// True when every required Firebase value was supplied.
  static bool get isConfigured =>
      _apiKey.isNotEmpty &&
      _appId.isNotEmpty &&
      _senderId.isNotEmpty &&
      _projectId.isNotEmpty;

  /// Firebase options for the current flavor.
  static FirebaseOptions get firebaseOptions => FirebaseOptions(
    apiKey: _apiKey,
    appId: _appId,
    messagingSenderId: _senderId,
    projectId: _projectId,
    storageBucket: _storageBucket.isEmpty ? null : _storageBucket,
    iosBundleId: _iosBundleId.isEmpty ? null : _iosBundleId,
    authDomain: kIsWeb && _webAuthDomain.isNotEmpty ? _webAuthDomain : null,
  );
}
